"""Extract the production API logger, with an optional old-signature control."""
import argparse
import hashlib
import json
from pathlib import Path


def extract(source, marker, terminator):
    if source.count(marker) != 1:
        raise ValueError(f"Expected one production marker: {marker}")
    start = source.index(marker)
    return source[start:source.index(terminator, start) + len(terminator)]


def prepare(source, output, old_signature=False):
    header = (source / "bridge/src/client/d3d9_util.h").read_text(encoding="utf-8")
    implementation = (source / "bridge/src/client/d3d9_lss.cpp").read_text(encoding="utf-8")
    declaration = extract(header, "class FunctionEntryExitLogger {", "\n};")
    macros = "\n".join(line for line in header.splitlines() if line.startswith((
        "#define LogFunctionCall()",
        "#define LogStaticFunctionCall()")))
    macros = "\n".join(line for line in macros.splitlines() if "FunctionEntryExitLogger" in line)
    if len(macros.splitlines()) != 2:
        raise ValueError("Expected both production function logging macros")
    marker = "std::map<std::thread::id, std::atomic<size_t>>& FunctionEntryExitLogger::counters()"
    if implementation.count(marker) != 1:
        raise ValueError("Expected one production logger implementation")
    start = implementation.index(marker)
    methods = implementation[start:implementation.index("\n#endif", start)]
    new = "FunctionEntryExitLogger(const char* functionName, void* thiz)"
    old = "FunctionEntryExitLogger(const std::string functionName, void* thiz)"
    if declaration.count(new) != 1 or methods.count(new) != 1:
        raise ValueError("Expected the allocation-free production logger signature")
    if old_signature:
        declaration = declaration.replace(new, old)
        methods = methods.replace(new, old)
    output.mkdir(parents=True, exist_ok=True)
    notices = header[:header.index("#ifndef D3D9_UTIL_H_")]
    outputs = {
        "function_logging_production.h": notices + "#pragma once\n" + declaration + "\n" + macros + "\n",
        "function_logging_production.inc": implementation[:implementation.index('#include')] + methods + "\n",
    }
    for name, contents in outputs.items():
        (output / name).write_text(contents, encoding="utf-8", newline="\n")
    metadata = {
        "variant": "old-signature" if old_signature else "current",
        "source_root": str(source.resolve()),
        "source_sha256": {
            "d3d9_util.h": hashlib.sha256(header.encode()).hexdigest(),
            "d3d9_lss.cpp": hashlib.sha256(implementation.encode()).hexdigest(),
        },
        "extracted_sha256": {name: hashlib.sha256(text.encode()).hexdigest() for name, text in outputs.items()},
        "boundary": "Actual production logger class, macros, constructor and destructor; configuration getters and log sink are test adapters. Crash observation and IPC API-entry scopes are no-op adapters, independently covered by native transport/diagnostic suites. No IPC, D3D or GPU work is measured.",
    }
    (output / "extraction.json").write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--old-signature", action="store_true")
    args = parser.parse_args()
    prepare(args.source, args.output, args.old_signature)
